using System.IO;
using System.Linq;
using CSObjectWrapEditor;
using NUnit.Framework;

// Runs the editor-side xLua tools inside a real Unity editor. Copied into the
// disposable project only when prepare.py is given --editor-tools.
public sealed class XluaEditorToolsTests
{
    // LuaCATS reads only the source generator's manifests ([assembly:
    // GeneratedBindings]) since milestone M11, and says where the configuration
    // came from: Assembly-CSharp's manifest in mode "sourcegen", none without
    // the generator (mode "reflection").
    [Test]
    public void LuaCATSDefinitionsAreGenerated()
    {
        var messages = new System.Collections.Generic.List<string>();
        UnityEngine.Application.LogCallback collect = (message, stack, type) => messages.Add(message);
        UnityEngine.Application.logMessageReceived += collect;
        try
        {
            Generator.GenLuaCATS();
        }
        finally
        {
            UnityEngine.Application.logMessageReceived -= collect;
        }
        string dir = GeneratorConfig.luacats_path;
        foreach (string name in new[] { "CS.lua", "xlua.lua" })
        {
            string file = Path.Combine(dir, name);
            FileAssert.Exists(file);
            StringAssert.StartsWith("---@meta", File.ReadAllText(file));
        }
        string from = messages.FirstOrDefault(m => m.StartsWith("LuaCATS: ")) ?? "(no LuaCATS: message)";
        TestContext.WriteLine("XLUA_EDITOR_LUACATS_FROM: " + from);
        if (XluaEditorTestSteps.ReadMode() == XluaEditorTestSteps.SourceGen)
        {
            StringAssert.Contains("Assembly-CSharp", from);
            StringAssert.Contains("comes from the xLua source generator's manifest", from);
        }
        else
        {
            StringAssert.StartsWith("LuaCATS: no assembly has bindings from the xLua source generator", from);
        }
    }

    // In mode "reflection" LuaCATS declares only xLua's own API: no file for
    // the configured type of `file`. Returns whether the suite's types are declared.
    internal static bool DeclaresConfiguredTypes(string file)
    {
        if (XluaEditorTestSteps.ReadMode() == XluaEditorTestSteps.SourceGen)
        {
            return true;
        }
        FileAssert.DoesNotExist(Path.Combine(GeneratorConfig.luacats_path, file), "declared without a manifest");
        StringAssert.DoesNotContain("CS.XluaEditorTest.", File.ReadAllText(Path.Combine(GeneratorConfig.luacats_path, "CS.lua")),
            "CS.lua declares the suite's types without a manifest");
        return false;
    }

    [Test]
    public void LuarcMatchesThePlugin()
    {
        Generator.GenLuaCATS();
        string luarc = Path.Combine(Path.GetDirectoryName(Path.GetFullPath(GeneratorConfig.luacats_path).TrimEnd('/', '\\')), ".luarc.json");
        FileAssert.Exists(luarc);
        string text = File.ReadAllText(luarc);
#if XLUA_SMOKE_LUA55
        StringAssert.Contains("\"runtime.version\": \"Lua 5.5\"", text);
#else
        StringAssert.Contains("\"runtime.version\": ", text);
#endif
        StringAssert.Contains("\"LuaTypes\"", text);
    }

    [Test]
    public void ClearAndGenerateKeepsUserFiles()
    {
        Generator.GenLuaCATS();
        string dir = GeneratorConfig.luacats_path;
        string user = Path.Combine(dir, "user-notes.lua");
        string stale = Path.Combine(dir, "Stale.Removed.lua");
        File.WriteAllText(user, "-- mine\n");
        File.WriteAllText(stale, File.ReadAllText(Path.Combine(dir, "CS.lua")));
        try
        {
            Generator.ClearAndGenLuaCATS();
            FileAssert.Exists(user);
            FileAssert.DoesNotExist(stale);
            FileAssert.Exists(Path.Combine(dir, "CS.lua"));
        }
        finally
        {
            File.Delete(user);
        }
    }

    [Test]
    public void ValidateSetupAcceptsThePlugin()
    {
        var problems = SetupValidator.Validate();
        // The project has no old xLua modules in Assets or Packages.
        Assert.IsFalse(problems.Any(p => p.StartsWith("Native plugin") || p.StartsWith("LuaCATS") || p.StartsWith("Stale module")),
            string.Join("\n", problems.ToArray()));
    }

    [Test]
    public void ValidateSetupReportsOldModulesInResources()
    {
        // An in-place upgrade leaves the Lua files xLua used to ship in Resources;
        // the Resources searcher would load them before the embedded modules.
        string root = Path.Combine(Path.GetTempPath(), "xlua-stale-" + System.Guid.NewGuid().ToString("N"));
        string util = Path.Combine(root, "Game/Resources/xlua/util.lua.txt");
        string ignored = Path.Combine(root, "Samples~/Resources/perf/profiler.lua.txt");
        Directory.CreateDirectory(Path.GetDirectoryName(util));
        Directory.CreateDirectory(Path.GetDirectoryName(ignored));
        try
        {
            File.WriteAllText(util, "return {}\n");
            File.WriteAllText(util + ".meta", "guid: 0\n");
            File.WriteAllText(ignored, "return {}\n");
            var problems = SetupValidator.CheckStaleModules(new[] { root });
#if XLUA_NO_UTIL
            Assert.AreEqual(0, problems.Count, string.Join("\n", problems.ToArray()));
#else
            Assert.AreEqual(1, problems.Count, string.Join("\n", problems.ToArray()));
            StringAssert.Contains(Path.GetFullPath(util) + " replaces the xlua.util module embedded in xLua", problems[0]);
            StringAssert.Contains("keep it only if you edited it on purpose", problems[0]);
#endif
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Test]
    public void HotfixToolsAreCheckedAgainstTheManifest()
    {
        // Validate Setup and the hotfix step compare the project's Hotfix.cs with
        // the one the injector was built from, as recorded by build_tools.py.
        string source = SetupValidator.FindHotfixSource();
        StringAssert.EndsWith("/Editor/Hotfix.cs", source);
        string tools = Path.Combine(Path.GetTempPath(), "xlua-tools-" + System.Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tools);
        try
        {
            File.WriteAllText(Path.Combine(tools, "XLuaHotfixInject.exe"), "");
            File.WriteAllText(Path.Combine(tools, SetupValidator.HotfixManifest),
                "hotfix-source-sha256=" + SetupValidator.HotfixSourceHash(source)
                + "\nfile=XLuaHotfixInject.exe\nfile=Mono.Cecil.Rocks.dll\n");
            bool unusable;
            var problems = SetupValidator.CheckHotfixTools(tools, source, out unusable);
            Assert.IsTrue(unusable, string.Join("\n", problems.ToArray()));
            Assert.AreEqual(1, problems.Count, string.Join("\n", problems.ToArray()));
            StringAssert.Contains("Mono.Cecil.Rocks.dll is missing", problems[0]);

            File.WriteAllText(Path.Combine(tools, "Mono.Cecil.Rocks.dll"), "");
            problems = SetupValidator.CheckHotfixTools(tools, source, out unusable);
            Assert.IsFalse(unusable);
            Assert.AreEqual(0, problems.Count, string.Join("\n", problems.ToArray()));
        }
        finally
        {
            Directory.Delete(tools, true);
        }
    }

    internal static string Definitions(string name)
    {
        string file = Path.Combine(GeneratorConfig.luacats_path, name);
        FileAssert.Exists(file);
        string text = File.ReadAllText(file).Replace("\r\n", "\n");
        StringAssert.StartsWith("---@meta\n", text);
        return text;
    }

    internal static void Has(string text, string file, params string[] lines)
    {
        foreach (string line in lines)
        {
            StringAssert.Contains(line, text, file + " lacks: " + line);
        }
    }

    // The types come from the configuration attributes in XluaEditorTestTarget.cs,
    // through Assembly-CSharp's manifest. editor_tests.py then runs
    // lua-language-server on these files (mode "sourcegen" only).
    [Test]
    public void LuaCATSDescribesUnityAndTestTypes()
    {
        Generator.GenLuaCATS();
        if (!DeclaresConfiguredTypes("XluaEditorTest.Target.lua"))
        {
            return;
        }

        Has(Definitions("UnityEngine.Vector3.lua"), "UnityEngine.Vector3.lua",
            "---@class CS.UnityEngine.Vector3 : CS.System.ValueType\n",
            "---@field x number\n",
            "---@field magnitude number read-only\n",
            "---@field up CS.UnityEngine.Vector3 static, read-only\n",
            "---@operator add(CS.UnityEngine.Vector3): CS.UnityEngine.Vector3\n",
            "---@overload fun(x: number, y: number, z: number): CS.UnityEngine.Vector3\n",
            "function CS.UnityEngine.Vector3.Cross(lhs, rhs) end\n");

        Has(Definitions("UnityEngine.GameObject.lua"), "UnityEngine.GameObject.lua",
            "---@class CS.UnityEngine.GameObject : CS.UnityEngine.Object\n",
            "---@field transform CS.UnityEngine.Transform read-only\n",
            "---@overload fun(name: string): CS.UnityEngine.GameObject\n");

        // Base classes are declared in full even though only GameObject is configured.
        Has(Definitions("UnityEngine.Object.lua"), "UnityEngine.Object.lua",
            "---@class CS.UnityEngine.Object : CS.System.Object\n",
            "function CS.UnityEngine.Object.DestroyImmediate(obj");

        Has(Definitions("UnityEngine.Transform.lua"), "UnityEngine.Transform.lua",
            "---@class CS.UnityEngine.Transform : CS.UnityEngine.Component",
            "---@field position CS.UnityEngine.Vector3\n",
            "function CS.UnityEngine.Transform:Find(n) end\n");

        Has(Definitions("XluaEditorTest.Target.lua"), "XluaEditorTest.Target.lua",
            "---@class CS.XluaEditorTest.Target : CS.System.Object\n",
            "---@field Value integer\n",
            "---@field Callback CS.XluaEditorTest.Combine\n",
            "---@field Calls integer static\n",
            "---@overload fun(value: integer): CS.XluaEditorTest.Target\n",
            "---@overload fun(self: CS.XluaEditorTest.Target, s: string): string\n",
            "---@overload fun(self: CS.XluaEditorTest.Target, x: integer, y: integer): string\n",
            "---@return integer rem\n",
            "function CS.XluaEditorTest.Target.Div(a, b) end\n",
            "---@return integer v\n",
            "function CS.XluaEditorTest.Target:Twice(v) end\n");

        Has(Definitions("XluaEditorTest.Mood.lua"), "XluaEditorTest.Mood.lua",
            "---@class CS.XluaEditorTest.Mood : CS.System.Enum\n",
            "---@field Calm CS.XluaEditorTest.Mood = 1\n",
            "---@field Lost CS.XluaEditorTest.Mood = 4\n");

        Has(Definitions("XluaEditorTest.Pair.lua"), "XluaEditorTest.Pair.lua",
            "---@class CS.XluaEditorTest.Pair : CS.System.ValueType\n",
            "---@field A integer\n",
            "---@field B number\n");

        Has(Definitions("CS.lua"), "CS.lua",
            "---@alias CS.XluaEditorTest.Combine fun(a: integer, b: string): integer\n");
    }

    // `in` parameters are plain arguments with no extra return value, so the
    // by-value and `in` overloads of Vector3.Distance (Unity 6.3+) are one entry.
    [Test]
    public void LuaCATSTreatsInParametersAsArguments()
    {
        Generator.GenLuaCATS();
        TestContext.WriteLine("XLUA_EDITOR_VECTOR3_IN_OVERLOADS: " + XluaGeneratedCodeTests.Vector3HasInOverloads);
        if (!DeclaresConfiguredTypes("XluaEditorTest.Target.lua"))
        {
            return;
        }

        string vector3 = Definitions("UnityEngine.Vector3.lua");
        Has(vector3, "UnityEngine.Vector3.lua",
            "---@param a CS.UnityEngine.Vector3|table\n---@param b CS.UnityEngine.Vector3|table\n---@return number\n"
            + "function CS.UnityEngine.Vector3.Distance(a, b) end\n");
        StringAssert.DoesNotContain("): number, CS.UnityEngine.Vector3", vector3, "extra returns for in parameters");
        StringAssert.DoesNotContain("---@return CS.UnityEngine.Vector3 a\n", vector3, "extra returns for in parameters");

        Has(Definitions("XluaEditorTest.Target.lua"), "XluaEditorTest.Target.lua",
            "---@param p CS.XluaEditorTest.Pair|table\n---@return number\nfunction CS.XluaEditorTest.Target.Length(p) end\n",
            "---@return number\n---@return integer factor\nfunction CS.XluaEditorTest.Target:Scaled(p, factor) end\n");

        Has(Definitions("CS.lua"), "CS.lua",
            "---@alias CS.XluaEditorTest.MeasurePair fun(p: CS.XluaEditorTest.Pair, calls: integer): number, integer\n");
    }
}
